const freeze=x=>{if(x&&typeof x==='object'){Object.values(x).forEach(freeze);Object.freeze(x);}return x;};
export const BATCH_MODEL_ID='whole-batches-v1';
export const BATCH_INGREDIENTS=freeze([{id:'cloud-water',name:'cloud-water',pattern:'dots',colour:'#729faf'},{id:'star-water',name:'star-water',pattern:'stripes',colour:'#b69b58'}]);
export const BATCH_MODEL=freeze({id:BATCH_MODEL_ID,revision:1,unit:'mL',baseGuests:2,base:{'cloud-water':100,'star-water':150},jugCapacity:500,jarCapacity:500,sourceAmount:1000,transfer:50,notice:'Pretend ingredients, exact pictured amounts. The preparation jars stay separate.',details:'mL names liquid volume. Capacity is the most a vessel can hold; each jug and preparation jar holds at most 500 mL. The two ingredient portions are not halves and are never mixed into one measured volume.'});
export const BATCH_CASES=freeze([
 ['rehearsal-table','Rehearsal table','Prepare a tray for the four-place rehearsal table.',4],
 ['story-supper','Outdoor story supper','Prepare a tray for the six-place outdoor story supper.',6],
 ['quiet-picnic','Quiet picnic','Prepare a tray for the two-place quiet picnic.',2]
].map(([id,title,purpose,guests])=>({id,title,purpose,destination:id,guests,copies:guests/2,modelId:BATCH_MODEL_ID,revision:1,unit:'mL',baseGuests:2,base:{'cloud-water':100,'star-water':150},targets:{'cloud-water':guests/2*100,'star-water':guests/2*150}})));
export const batchById=id=>BATCH_CASES.find(c=>c.id===id)||null;
