export const BATCH_GLOSSARY=freeze({whole:'The complete thing we are talking about.',batch:'Both named portions together, enough for two guests.',copy:'Another complete batch with the same named amounts.',guest:'One counted place at the gathering.',volume:'How much liquid is in a vessel now, pictured in mL.',capacity:'The most a vessel can hold: 500 mL here.'});
export const BATCH_TEACHING=freeze({whole:'The same loaf can be shared into two equal halves, then four equal quarters. One quarter is one equal share of that same loaf. Now change the whole: one complete recipe batch is 100 mL cloud-water and 150 mL star-water together for two guests. These unequal jars are not halves.',base:'Keep each number with its thing: 100 mL cloud-water, 150 mL star-water, two counted guests.',copies:'Repeat the complete batch. Each card adds two guests and both named portions. Removing a card removes that complete group. Three copies mean three times each base amount, not three mL more.',contrast:'Two copies use 200 mL cloud-water and 300 mL star-water. Adding 100 mL to each gives 300/400; adding a complete batch gives 300/450. The star-water distinguishes the plans.',reference:'Familiar supplied practice: two matching complete cards serve four guests with 200 mL cloud-water and 300 mL star-water. Find the amount on one two-guest base card, not one guest’s plate.',scale:'The jug has ten equal 50 mL intervals. Read its current liquid volume separately from the request. A correct 300 mL reading stays correct when the request wanted 200 mL.',message:'Name the destination, guests and both ingredient amounts with mL. Supplied phrases help make an unambiguous order.',ending:'One tray joins the gathering. Different contributions are welcome; the story stays open.'});
export const BATCH_CONVERSATION='What stays the same in every complete batch, and what changes when we add a copy?';
